  isInExpressionMode(): boolean { return !this.isInRelationshipsMode() }
  private _resolveMembershipExpression(active: Set<string>): SdfPathExpression | undefined {
    const identity = `${this.prim.path}:${this._name}`
    if (active.has(identity)) return SdfPathExpression.Nothing()
    const value = this.getMembershipExpressionAttr().get()
    const expression = value instanceof SdfPathExpression ? value
      : typeof value === 'string' ? new SdfPathExpression(value) : undefined
    if (!expression) return undefined
    active.add(identity)
    const resolved = expression.resolveReferences(reference => {
      const ownerPath = reference.path.isEmpty()
        ? this.prim.path
        : reference.path.pathString
      const nested = CollectionAPI.get(
        this.stage, `${ownerPath}.collection:${reference.name}`)
      return nested._resolveMembershipExpression(active) ?? SdfPathExpression.Nothing()
    })
    active.delete(identity)
    return resolved
  }
