// UsdDescribe(const UsdStage *) (stage.cpp:10323-10334).
function usdDescribeStage(stage: Stage): string {
  const session = stage.getSessionLayer()
  return `stage with rootLayer @${stage.getRootLayer().identifier}@`
    + (session ? `, sessionLayer @${session.identifier}@` : '')
}
